/**
 * Checkout screen.
 *
 * Sits between "Buy ticket" and the ticket existing. Three states in
 * one route - form, processing, done - rather than three screens,
 * because the user is in a single task and pushing routes for each
 * step would make the back button mean something unhelpful halfway
 * through a payment.
 *
 * PAYMENT IS SIMULATED. Card details never leave this screen: they are
 * validated locally, a reference is generated by mockAuthorise(), and
 * only that reference is sent with the purchase. Swapping in a real
 * gateway would mean replacing one function, not rewriting the flow.
 */
import { mockAuthorise, validateCard, type CardDraft, type CardFieldError } from "@eventpass/shared";
import { router, useLocalSearchParams } from "expo-router";
import { ArrowLeft, CheckCircle, CreditCard, LockSimple, Plus, ShieldWarning, Trash } from "phosphor-react-native";
import { useCallback, useEffect, useState } from "react";
import {
  ActivityIndicator,
  KeyboardAvoidingView,
  Platform,
  Pressable,
  ScrollView,
  TextInput,
  View,
} from "react-native";
import { CardInput } from "@/components/card-input";
import { PaymentProgress, type PaymentStep } from "@/components/payment-progress";
import { EventImage } from "@/components/event-image";
import { Button } from "@/components/ui/button";
import { PhosphorIcon } from "@/components/ui/phosphor-icon";
import { Text } from "@/components/ui/text";
import { useEvents } from "@/lib/use-events";
import { useTickets } from "@/lib/use-tickets";
import {
  describeCard,
  getSavedCards,
  removeSavedCard,
  saveCard,
  type SavedCard,
} from "@/lib/saved-cards";

const EMPTY: CardDraft = { number: "", expiry: "", cvc: "", name: "" };

/** Mock pricing: events carry no price field, so one is derived from
 *  capacity purely so the summary has something concrete to show. */
function priceFor(capacity: number): number {
  return capacity > 300 ? 2500 : capacity > 100 ? 1500 : 950;
}

const money = (cents: number) => `LKR ${cents.toLocaleString()}`;

export default function CheckoutScreen() {
  const { eventId } = useLocalSearchParams<{ eventId: string }>();
  const { events } = useEvents();
  const { purchaseTicket } = useTickets();

  const [card, setCard] = useState<CardDraft>(EMPTY);
  const [saved, setSaved] = useState<SavedCard[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [shouldSave, setShouldSave] = useState(true);
  const [errors, setErrors] = useState<CardFieldError[]>([]);
  const [stage, setStage] = useState<"form" | "processing" | "done">("form");
  const [failure, setFailure] = useState<string | null>(null);
  const [step, setStep] = useState<PaymentStep>("validate");
  const [failedStep, setFailedStep] = useState<PaymentStep | null>(null);

  const event = events.find((e) => e.id === eventId);

  const loadCards = useCallback(async () => {
    try {
      const cards = await getSavedCards();
      setSaved(cards);
      // Preselect the most recent card so the common case is one tap.
      setSelectedCardId((current) => current ?? cards[0]?.id ?? null);
    } catch {
      // A local-storage failure must not block paying.
      setSaved([]);
    }
  }, []);

  useEffect(() => {
    loadCards();
  }, [loadCards]);

  const selectedCard = saved.find((c) => c.id === selectedCardId) ?? null;

  if (!event) {
    return (
      <View className="bg-background flex-1 items-center justify-center gap-4 p-6">
        <Text className="font-title text-center text-lg">This event couldn't be found.</Text>
        <Button className="rounded-md" onPress={() => router.back()}>
          <Text>Back</Text>
        </Button>
      </View>
    );
  }

  const price = priceFor(event.capacity);
  const fee = Math.round(price * 0.06);

  async function handlePay() {
    if (!event) return;

    // --- validate -------------------------------------------------
    // Validate only on submit; flagging fields while someone is still
    // typing their first digit is hostile.
    if (selectedCard) {
      // A saved card supplies brand/expiry/name but NOT the number -
      // it was never stored - so only the CVC is required.
      if (card.cvc.length < 3) {
        setErrors([{ field: "cvc", message: "Enter the security code" }]);
        return;
      }
      setErrors([]);
    } else {
      // Demo mode: payment is simulated, so any plausible card number
      // is accepted. The full rules still exist and are tested.
      const found = validateCard(card, new Date(), { strict: false });
      setErrors(found);
      if (found.length > 0) return;
    }

    setFailure(null);
    setFailedStep(null);
    setStep("validate");
    setStage("processing");

    // Each step below is real work. The short pauses stand in for the
    // network latency a hosted gateway would add - without them the
    // first two steps complete in under a millisecond and the user
    // sees a flicker rather than feedback. Only the reserve step
    // actually touches the network.
    const beat = (ms: number) => new Promise((r) => setTimeout(r, ms));

    await beat(450);

    // --- authorise ------------------------------------------------
    setStep("authorise");
    const paymentRef = selectedCard
      ? `SIM-${selectedCard.brand.toUpperCase()}-${selectedCard.last4}-${Date.now().toString(36).toUpperCase()}`
      : mockAuthorise(card);
    await beat(700);

    // --- reserve (the only step that can genuinely fail) ----------
    setStep("reserve");
    const result = await purchaseTicket(event.id, paymentRef);

    if (!result.ok) {
      // Fails AT the reserve step, so the user can see payment was
      // never completed rather than wondering if they were charged.
      setFailedStep("reserve");
      setFailure(result.error);
      await beat(1200);
      setStage("form");
      return;
    }

    // --- issue ----------------------------------------------------
    setStep("issue");

    if (!selectedCard && shouldSave) {
      // Persists brand/last4/expiry/name only.
      try {
        await saveCard(card);
      } catch {
        // Not worth failing a completed payment over.
      }
    }
    await beat(500);

    // Clear the draft the moment it is no longer needed.
    setCard(EMPTY);
    setStage("done");
  }

  if (stage === "done") {
    return (
      <View className="bg-background flex-1 items-center justify-center gap-5 p-8">
        <PhosphorIcon as={CheckCircle} size={64} weight="fill" className="text-primary" />
        <View className="items-center gap-2">
          <Text className="font-display text-center text-3xl">Payment complete</Text>
          <Text variant="muted" className="text-center">
            Your ticket for {event.title} is in your wallet, and works offline.
          </Text>
        </View>
        <View className="mt-2 w-full gap-2">
          <Button className="rounded-md" onPress={() => router.replace("/tickets")}>
            <Text>View my ticket</Text>
          </Button>
          <Button variant="outline" className="rounded-md" onPress={() => router.replace("/")}>
            <Text>Back to Discover</Text>
          </Button>
        </View>
      </View>
    );
  }

  return (
    <KeyboardAvoidingView
      className="bg-background flex-1"
      behavior={Platform.OS === "ios" ? "padding" : undefined}
    >
      <ScrollView
        contentContainerStyle={{ padding: 20, paddingTop: 64, paddingBottom: 40 }}
        keyboardShouldPersistTaps="handled"
        showsVerticalScrollIndicator={false}
      >
        <Pressable
          onPress={() => router.back()}
          accessibilityLabel="Go back"
          className="border-border bg-card mb-5 h-10 w-10 items-center justify-center rounded-full border"
        >
          <PhosphorIcon as={ArrowLeft} size={18} weight="bold" />
        </Pressable>

        <Text className="text-primary font-ui text-sm">Checkout</Text>
        <Text className="font-display mb-5 text-4xl">Confirm and pay</Text>

        {/* Order summary */}
        <View className="border-border bg-card rounded-card mb-5 border p-4">
          <View className="flex-row items-center gap-3">
            <View className="bg-elevated h-14 w-14 overflow-hidden rounded-art">
              <EventImage imageKey={event.imageKey} className="h-full w-full" iconSize={18} />
            </View>
            <View className="flex-1">
              <Text numberOfLines={2} className="font-title text-base">{event.title}</Text>
              <Text variant="muted" numberOfLines={1}>{event.venue.name}</Text>
            </View>
          </View>

          <View className="bg-border my-4 h-px" />

          <View className="gap-1.5">
            <View className="flex-row justify-between">
              <Text variant="muted">General admission</Text>
              <Text className="font-ui text-sm">{money(price)}</Text>
            </View>
            <View className="flex-row justify-between">
              <Text variant="muted">Booking fee</Text>
              <Text className="font-ui text-sm">{money(fee)}</Text>
            </View>
            <View className="bg-border my-1.5 h-px" />
            <View className="flex-row items-baseline justify-between">
              <Text className="font-title text-base">Total</Text>
              <Text className="font-display text-xl">{money(price + fee)}</Text>
            </View>
          </View>
        </View>

        {/* Simulation notice- stated plainly, not buried. */}
        <View className="border-border bg-card mb-5 flex-row items-start gap-2.5 rounded-md border p-3">
          <PhosphorIcon as={ShieldWarning} size={18} className="text-primary mt-0.5" />
          <View className="flex-1">
            <Text className="font-title text-sm">Simulated payment</Text>
            <Text variant="muted" className="text-xs">
              No real card is charged and no card details are stored or sent anywhere. Use a test
              number such as 4242 4242 4242 4242.
            </Text>
          </View>
        </View>

        {/* Saved cards. Shows brand/last4/expiry only, because that is
            all that was ever stored- the number is not retained, which
            is why reusing one still asks for the CVC. */}
        {saved.length > 0 ? (
          <View className="mb-5 gap-2">
            <Text className="font-heading text-xl">Pay with</Text>
            {saved.map((c) => {
              const active = c.id === selectedCardId;
              return (
                <Pressable
                  key={c.id}
                  onPress={() => setSelectedCardId(c.id)}
                  accessibilityRole="radio"
                  accessibilityState={{ selected: active }}
                  accessibilityLabel={`${describeCard(c)}, expires ${c.expiry}`}
                  className={
                    active
                      ? "border-primary bg-card flex-row items-center gap-3 rounded-md border p-3"
                      : "border-border bg-card flex-row items-center gap-3 rounded-md border p-3"
                  }
                >
                  <PhosphorIcon
                    as={CreditCard}
                    size={20}
                    weight={active ? "fill" : "regular"}
                    className={active ? "text-primary" : "text-muted-foreground"}
                  />
                  <View className="flex-1">
                    <Text className="font-title text-base">{describeCard(c)}</Text>
                    <Text variant="muted">
                      {c.name} · expires {c.expiry}
                    </Text>
                  </View>
                  <Pressable
                    onPress={async () => {
                      await removeSavedCard(c.id);
                      if (selectedCardId === c.id) setSelectedCardId(null);
                      loadCards();
                    }}
                    accessibilityRole="button"
                    accessibilityLabel={`Remove ${describeCard(c)}`}
                    hitSlop={10}
                  >
                    <PhosphorIcon as={Trash} size={18} className="text-muted-foreground" />
                  </Pressable>
                </Pressable>
              );
            })}

            <Pressable
              onPress={() => {
                setSelectedCardId(null);
                setCard(EMPTY);
                setErrors([]);
              }}
              accessibilityRole="radio"
              accessibilityState={{ selected: selectedCardId === null }}
              accessibilityLabel="Use a different card"
              className={
                selectedCardId === null
                  ? "border-primary bg-card flex-row items-center gap-3 rounded-md border p-3"
                  : "border-border bg-card flex-row items-center gap-3 rounded-md border border-dashed p-3"
              }
            >
              <PhosphorIcon as={Plus} size={20} className="text-muted-foreground" />
              <Text className="font-title text-base">Use a different card</Text>
            </Pressable>
          </View>
        ) : null}

        {selectedCard ? (
          // Reusing a saved card: only the CVC is missing, because the
          // number was deliberately never stored.
          <View className="gap-2">
            <Text className="text-muted-foreground font-ui text-sm">
              Security code for {describeCard(selectedCard)}
            </Text>
            <TextInput
              value={card.cvc}
              onChangeText={(t) => {
                setCard({ ...card, cvc: t.replace(/\D/g, "").slice(0, 4) });
                setErrors((prev) => prev.filter((e) => e.field !== "cvc"));
              }}
              placeholder="•••"
              placeholderTextColor="#8A8276"
              keyboardType="number-pad"
              secureTextEntry
              editable={stage !== "processing"}
              accessibilityLabel="Security code"
              className="border-border bg-card text-foreground font-sans w-28 rounded-md border px-3 py-3 text-base"
            />
            {errors.find((e) => e.field === "cvc") ? (
              <Text className="text-destructive font-ui text-xs">
                {errors.find((e) => e.field === "cvc")?.message}
              </Text>
            ) : null}
          </View>
        ) : (
          <>
            <CardInput
              value={card}
              // Clear a field's error as soon as it is edited. Keeping
              // errors until the next submit leaves "Enter a valid
              // future date" sitting under a date the user has just
              // corrected, which reads as the app being wrong.
              onChange={(next) => {
                setCard(next);
                setErrors((prev) =>
                  prev.filter((e) => {
                    if (e.field === "number") return next.number === card.number;
                    if (e.field === "expiry") return next.expiry === card.expiry;
                    if (e.field === "cvc") return next.cvc === card.cvc;
                    return next.name === card.name;
                  })
                );
              }}
              errors={errors}
              disabled={stage === "processing"}
            />
            <Pressable
              onPress={() => setShouldSave((v) => !v)}
              accessibilityRole="checkbox"
              accessibilityState={{ checked: shouldSave }}
              accessibilityLabel="Save this card for next time"
              className="mt-4 flex-row items-center gap-2.5"
            >
              <View
                className={
                  shouldSave
                    ? "bg-primary border-primary h-5 w-5 items-center justify-center rounded-sm border"
                    : "border-border h-5 w-5 rounded-sm border"
                }
              >
                {shouldSave ? (
                  <PhosphorIcon
                    as={CheckCircle}
                    size={13}
                    weight="fill"
                    className="text-primary-foreground"
                  />
                ) : null}
              </View>
              <Text variant="muted" className="flex-1">
                Save this card for next time (last 4 digits only)
              </Text>
            </Pressable>
          </>
        )}

        {failure ? (
          <Text className="text-destructive font-ui mt-4 text-sm">{failure}</Text>
        ) : null}

        <Button
          className="mt-6 h-14 rounded-md"
          onPress={handlePay}
          disabled={stage === "processing"}
        >
          {stage === "processing" ? (
            <ActivityIndicator color="#141210" />
          ) : (
            <PhosphorIcon as={LockSimple} size={16} weight="fill" className="text-primary-foreground" />
          )}
          <Text>{stage === "processing" ? "Processing..." : `Pay ${money(price + fee)}`}</Text>
        </Button>

        <Text variant="muted" className="mt-3 text-center text-xs">
          Tickets are non-refundable. Capacity is confirmed at the moment of payment.
        </Text>
      </ScrollView>

      {stage === "processing" ? (
        <PaymentProgress current={step} failedAt={failedStep} errorMessage={failure} />
      ) : null}
    </KeyboardAvoidingView>
  );
}
